H.background();
const v = H.plot2d({ xMin: 0, xMax: 8, yMin: -3, yMax: 3 });
v.grid(); v.axes();
const A = Math.max(0.1, P.A), lambda = Math.max(0.3, P.lambda), f = Math.max(0.1, P.f);
// Traveling wave y(x,t) = A sin(k x - w t), k = 2pi/lambda, w = 2pi f.
const k = 2 * Math.PI / lambda, w = 2 * Math.PI * f;
v.fn(x => A * Math.sin(k * x - w * t), { color: H.colors.accent, width: 3 });
// Amplitude bracket (vertical double arrow) at left.
v.arrow(0.5, 0, 0.5, A, { color: H.colors.warn, width: 2 });
v.arrow(0.5, 0, 0.5, -A, { color: H.colors.warn, width: 2 });
v.text("A", 0.7, A * 0.6, { color: H.colors.warn, size: 13 });
// Wavelength marker: distance between two crests at a fixed time snapshot.
// Crest nearest x=2 then the next crest one lambda further.
const phase = -w * t;
const firstCrest = (Math.PI / 2 - phase) / k;
let c0 = firstCrest;
while (c0 < 1.5) c0 += lambda;
while (c0 > 1.5 + lambda) c0 -= lambda;
v.arrow(c0, 2.4, c0 + lambda, 2.4, { color: H.colors.good, width: 2 });
v.arrow(c0 + lambda, 2.4, c0, 2.4, { color: H.colors.good, width: 2 });
v.text("lambda", c0 + lambda * 0.5 - 0.2, 2.7, { color: H.colors.good, size: 12 });
// A particle of the medium just oscillates up/down (no net travel).
const px = 6;
v.dot(px, A * Math.sin(k * px - w * t), { r: 6, fill: H.colors.violet });
H.text("Wave properties: amplitude, wavelength, frequency", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("A = " + A.toFixed(1) + " m   lambda = " + lambda.toFixed(1) + " m   f = " + f.toFixed(1) + " Hz   T = " + (1 / f).toFixed(2) + " s", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "amplitude A", color: H.colors.warn }, { label: "wavelength", color: H.colors.good }, { label: "medium point", color: H.colors.violet }], H.W - 190, 28);
